var owsUrl = ($('#ows_url').getValue());
var coords = ($('#aoi_coords').getValue()).split(' ');


var osmLayer = new ol.layer.Tile({
    className: 'bw100',
    source: new ol.source.OSM()
});


var districtLayer = new ol.layer.Tile({
    title: 'Districts',
    source: new ol.source.TileWMS({
        url: owsUrl,
        params: {
            'LAYERS': 'district',
            serverType: 'mapserver'
        }
    })
});


// Vector layer for the boundary of the district where the survey takes place
var wfsParams = '&typename=wfms:survey_district' +
                '&service=WFS&version=1.1.0&request=GetFeature' +
                '&outputFormat=geojson&srsname=EPSG:3857';
var surveyAreaLayer = new ol.layer.Vector({
    title: 'Survey District',
    source: new ol.source.Vector({
        format: new ol.format.GeoJSON(),
        url: owsUrl + wfsParams + '&COORDS=' + coords[0] + ' ' + coords[1]
    }),
    style: new ol.style.Style({
        stroke: new ol.style.Stroke({
            color: 'rgb(100, 149, 237)',
            width: 2.5
        }),
        fill: new ol.style.Fill({
            color: 'rgba(100, 149, 237, 0.1)'
        })
    })
});


// Compute the survey district's bounding box and store the value in the 'ows_extent' variable
var districtCode, recenter = true;
surveyAreaLayer.getSource().on('change', function(){
    if (recenter){
        var extent = this.getExtent();
        navmap.getView().setCenter(ol.extent.getCenter(extent));
        navmap.getView().fit(extent, navmap.getSize());
        navmap.getView().setZoom(navmap.getView().getZoom() - 0.3);
        $("#ows_extent").setValue((navmap.getView().calculateExtent(navmap.getSize())).toString());

        $("#district_name").setValue(this.getFeatures()[0].getProperties().district_name);
        districtCode = this.getFeatures()[0].getProperties().district_code;
        recenter = false;
    }
});


// Vector layer for survey data
var lotLayer = new ol.layer.Vector({
    title: 'Survey',
    source: new ol.source.Vector(),
    style: new ol.style.Style({
        fill: new ol.style.Fill({
            color: 'rgba(166, 77, 255, 0.1)'
        }),
        stroke: new ol.style.Stroke({
            color: 'rgb(166, 77, 255)',
            width: 2.5
        }),
        zIndex: 10
    })
});


var navmap = new ol.Map({
    layers: [osmLayer, districtLayer, surveyAreaLayer, lotLayer],
    target: 'navmap_div',
    view: new ol.View({
        extent: ol.proj.transformExtent([6.6104, 52.1542, 7.1531, 52.2922], 'EPSG:4326', 'EPSG:3857'),
        center: ol.proj.transform([6.8819, 52.2232], 'EPSG:4326', 'EPSG:3857'),
        zoom: 12, minZoom: 11, maxZoom: 16
    })
});


// Define a interaction object for on-screen digitizing
var drawLot = new ol.interaction.Draw({
    source: lotLayer.getSource(),
    type: 'Polygon'
});
drawLot.on('drawstart', function(){
    lotLayer.getSource().clear();
});
navmap.addInteraction(drawLot);


// Enable snaping of the surveyed lot inputs to the district boundary
navmap.addInteraction(new ol.interaction.Snap({
    source: surveyAreaLayer.getSource(),
}));


// Specifying what to do when a lot survey is completed
var lotSize;
lotLayer.getSource().on('addfeature', function(){
    var surveyCoords = $.extend(true, {}, this.getFeatures()[0].getGeometry());
    surveyCoords = surveyCoords.transform('EPSG:3857','EPSG:4326');
    $("#survey_coords").setValue(JSON.stringify(surveyCoords.getCoordinates()[0]));

    lotSize = ol.sphere.getArea(this.getFeatures()[0].getGeometry());
    $("#lot_size").setValue((Math.round((lotSize/10000)*100)/100).toString() + ' Hectares.');

    $("#selected_lot").setValue(districtCode + '-s' + (1 + Math.floor(Math.random() * 100)));
});
